X = {32638202: "c'è", 32638205: "c'era", 32640788: 'essere avvelenati', 32366996: 'bello', 32367001: 'bella', 32433635: 'guardare la TV', 32819033: 'ragazza', 32535399: 'un Pokémon raro', 9237803: 'un Pokémon raro', 32597136: 'amicooooo', 32597147: 'amicaaaaaa', 32601329: 'tesoro', 7924808: 'tesoro', 7924814: 'tesoro', 33087977: 'allo Spettacolo Lotta', 33087982: 'alla Sala Lotta', 33078997: 'la Direttrice del Circo', 33086758: 'il Magnate della Torre', 33144285: 'il Boss di Antisis', 33021258: 'Primavera', 33021272: 'Autunno', 7945496: 'Estate', 7945510: 'Inverno', 32419554: '§1 Baccapesca↓1 Baccaloquat↓1 Acqua fresca', 32419597: '§3 Baccafrago↓5 Baccartillo↓5 Baccacomero↓5 Latte Mumu', 7920073: '§1 Baccapesca↓1 Baccaloquat↓1 Latte Mumu', 7920178: '§10 Baccastagna↓10 Baccafrago↓5 Baccalighia', 4188202: 'sonno', 4188208: 'avvelenamento', 4188215: 'scottatura', 4188220: 'paralisi', 4188230: 'congelamento', 4188234: 'confusione', 4188244: 'infatuazione', 10798582: 'stato mentale', 10765045: 'attive', 10765048: 'disattivate', 10765052: 'potranno', 10765060: 'non potranno', 1727985: '[player] ottiene\n[buffer1]!', 32788246: '[rival], io…'}
R = {'scr_17D80D': 'Ehi! Come va?¶Hai già fatto un salto al laboratorio del Professor Log?', 'scr_194234': "L'impulso di combattere con qualcuno con cui hai già lottato…¶Ti è mai venuto? Sono sicuro di sì.¶Anch'io volevo affrontare certe persone ancora e ancora.¶Così ne ho distribuiti alcuni. Per favore, prendine uno!", 'scr_1EE8520': "L'impulso di combattere con qualcuno con cui hai già lottato…¶Ti è mai venuto? Sono sicuro di sì.¶Anch'io volevo affrontare certe persone ancora e ancora.¶Così ne ho distribuiti alcuni. Per favore, prendine uno!", 'scr_1954DD': 'Ciao! Ti diamo il benvenuto nei Grandi Magazzini di Dehara!¶La bacheca sulla parete descrive la disposizione del negozio.', 'scr_1EFDF59': 'Ciao! Ti diamo il benvenuto nei Grandi Magazzini di Dehara!¶La bacheca sulla parete descrive la disposizione del negozio.', 'scr_196AF3': 'Ehi, vuoi giocare?', 'scr_1A7063': 'Hai raggiunto le 100 specie! Che bravura incredibile!', 'scr_1A7108': 'Eccezionale! Ormai sei un vero asso!', 'scr_1BC311': 'Ti diamo il benvenuto nel Club Cavo Pokémon.¶Quale dei nostri servizi desideri usare?', 'scr_1BD28D': "Ti diamo il benvenuto nell'Angolo Diretto del Club Wireless Pokémon.¶Qui puoi interagire direttamente con i tuoi amici.¶In quale stanza vuoi entrare?", 'scr_1BD65B': 'Ti diamo il benvenuto nella Sala Unione del Club Wireless Pokémon. Qui puoi interagire direttamente con altri¶Allenatori, alcuni dei quali potresti non conoscere nemmeno. Vuoi entrare nella stanza?', 'scr_26D733': 'Oh, va bene allora. Se cambi idea torna pure quando vuoi!', 'tbl_battle_messages_00408_3FDDEB': 'Log: Mh… Che delusione…¶Se vinci, ottieni denaro in premio e i tuoi Pokémon crescono.¶Ma se perdi, @23, sei tu a dover pagare…¶Visto che nessuno ti aveva avvertito, stavolta pago io per te.¶Ma fuori da queste porte nessuno ti farà sconti.¶Per questo devi rafforzare i tuoi Pokémon lottando contro quelli selvatici.', 'scr_416008': "Ecco l'Albo d'Onore!", 'scr_41CE3C': 'Pronti per il BERRY-CRUSH? Scegli una Bacca da usare.¶', 'scr_4583F8': 'Se vuoi fare qualcosa con me, non farti problemi.¶', 'scr_458AB8': 'Ecco la BACHECA SCAMBI. Puoi registrare il tuo Pokémon e offrirlo in scambio. Vuoi registrare uno dei tuoi Pokémon?', 'scr_74159F': "Ah, sei tu! Un Campione in erba! Non ti avevo visto! Ti do il benvenuto alla Palestra di Città Cratere! Iniziamo con un po' di Acqua Fresca.", 'scr_78E3D1': "Oh, sei tu! Un campione in divenire!¶Ti piace il clima quassù?¶Ti do il benvenuto nella Palestra di Città Bufera!¶Iniziamo con un po' di Acqua fresca.", 'scr_7AC678': "Campione in erba!¶Ti do il benvenuto nelle baraccopoli di Città di Antisis, flagellate dal crimine!¶Prendi un po' di Acqua fresca direttamente dal mio rubinetto.", 'scr_7B5EE6': "Campione in erba! Come vanno le lotte?¶Ti do il benvenuto nella Palestra di Fallshore!¶Prendi un po' di Acqua fresca, direttamente dagli stagni di questa Palestra.", 'scr_7416E8': "Ben fatto! Ce l'hai fatta a farti strada nel buio e a sconfiggere Véga! Prendi questo, come ricompensa extra per la tua vittoria.", 'scr_788CAB': 'Sono colpito! Hai battuto Mirskle persino con gli occhi pieni di @qofog@qc! Prendi questo come ulteriore prova della tua vittoria qui.', 'scr_744BBF': 'Ehi, ciao!¶-COF- -COF-¶Ti do il benvenuto alla tua prima Sfida in Palestra!¶Lascia che ti dia un piccolo regalo.¶-COF- -AFFANNO-', 'scr_74FD41': 'Dove credi di andare? Ho ordini severi di non farti uscire.', 'scr_75C6DE': 'Recluta: [blue]Indietro! Ho ordini tassativi di non farti uscire.', 'scr_74FF66': 'Che sta succedendo? … Oh, aspetta… Tu abiti in fondo alla strada. [player], giusto? Sai cosa stiamo facendo qui?', 'scr_7504B7': "Avorio: [red]Moltres è sigillato. Sto tornando all'HQ. Potresti occuparti di chi ci sta guardando, prima di raggiungermi.", 'scr_75097E': "Arthur: [blue]Bene, bene. Quanto a te, [player], voglio che tu vada al [green]Monte Thundercap [blue]e salvi [green]Zapdos[blue]. Hai dato prova del tuo valore difendendo Jax nel Vulcano delle Ceneri, e penso che tu sia all'altezza dell'incarico. Puoi raggiungere il [green]Monte Thundercap [blue]prendendo l'autostrada a sud-est dalla città successiva, [green]Città Cratere[blue]. Se non ti sbrighi, la regione di Borrius sarà condannata.", 'scr_75BE75': 'Mi spiace, ma questa non è la strada giusta.', 'scr_75C74E': 'Sgherro: [blue]Scelta intelligente. Tieniti alla larga da questa porta e non te ne pentirai.', 'scr_76CE9D': 'Ti aspetta una bella scossa! Ho appena richiamato tutte le reclute di guardia al varco, quindi ora siamo dappertutto su questa strada!', 'scr_770AF7': 'Vattene, peste.', 'scr_770D88': 'Nessuno è autorizzato a entrare a Borgo Tehl in questo momento. Sparisci!', 'scr_7A3FD4': 'Nessuno di Borgo Tehl può andarsene da questa parte, in questo momento. Fila via!', 'scr_771A25': 'Alt! Dove credi di andare? Se pensi di poter affrontare la Grotta Ghiacciata, dimostramelo consegnando [green]il pacco di Log[blue] a lui.', 'scr_77258B': 'Peggio per te.', 'scr_1EE89A9': 'Peggio per te.', 'scr_775CE2': "[rival]: [blue]Che delusione. Pensavo davvero che ce l'avresti fatta contro di lui. Credo che me ne occuperò io. Usa questa Pozione sul tuo Pokémon per farlo stare meglio.", 'scr_77922B': "[blue]Oh, un'altra cosa. Appena torni a casa, lotteremo. Prima hai battuto in ritirata, ma la prossima volta non ti lascerò scappare! Fino ad allora, non stancarti troppo.", 'scr_779594': "[rival]: [blue][player]! Finalmente ce l'hai fatta a uscire!", 'scr_7815FC': 'Accidenti…¶Prendi questa bella, bellissima Medaglia come prova della tua vittoria…', 'scr_788F69': 'Uffa…¶Hai già Laccioerboso…', 'scr_788674': '[blue]Davvero pensavi che avrei mollato il pacco anche se avessi perso? Non sono venuto fin qui solo per cedere a una stupida peste qualunque. Ora spostati!', 'scr_78903B': 'Agente 1: [blue]Ehi, tu! Hai visto in che direzione è scappato il Capopalestra? È ricercato per traffico di foglie di Oddish!', 'scr_78BA4F': '[blue]Dici sul serio? È sempre utile avere una buona entratura con il Professor Pokémon!', 'scr_78CE6A': "Quest'area è vietata a chiunque non sia un membro delle Ombre. Visto che non sei dei nostri, sparisci!", 'scr_78D50F': 'Ah, dal distintivo sulla tua Carta Allenatore vedo che ormai lotti con notevole abilità. Hai superato da tempo il ruolo di [buffer1] tuttofare di Log.', 'scr_78E11A': "Ho, ho, ho!¶L'espressione sulla tua faccia è impagabile!¶Non preoccuparti: il [green]Maestro Taglio[blue] mi ha avvisato del tuo arrivo!", 'scr_1EEA4ED': "Ho, ho, ho!¶L'espressione sul tuo viso è impagabile!¶Non preoccuparti: il Maestro Taglio mi ha avvisato del tuo arrivo!", 'scr_78FA4B': 'Una Gemma è un tipo speciale di strumento tenuto che potenzia un singolo attacco in battaglia, per poi scomparire per sempre. Ogni Gemma corrisponde a un tipo specifico e può potenziare solo mosse di quel tipo. Ogni Capopalestra di Borrius ha almeno uno dei propri Pokémon che tiene una Gemma, quindi fai attenzione. Se la cosa ti preoccupa, puoi usare la mossa [green]Incenerimento[blue] per fondere prima la loro Gemma, prima che abbiano la possibilità di usarla.', 'scr_78FC07': "Ciprian: [blue]Non tollererò errori! L'ultima volta qualcuno ci ha notati e ha cercato di interferire.¶Non posso permettere che succeda di nuovo. Non abbiamo il lusso di occuparci di [buffer1] adesso.¶Mantenete un basso profilo a ogni costo e, qualunque cosa accada, non fatevi notare! Sono stato chiaro?", 'scr_791DB3': "[blue]Grazie di avermi seguito. … Che cos'è? Non è che avevi davvero scelta? Che sciocchezze. Non so di cosa tu stia parlando. Passiamo agli affari.", 'scr_7A5A40': 'Jax: [blue]Oh, ehi, [player]. Quindi hanno mandato qui anche te, eh? … Capisco…', 'scr_7AA4DF': "Vedi quell'oggetto sul tavolo? Quello è il mio bene più prezioso, il [green]Master Ball[red]. È una rara Poké¶Ball che può catturare qualsiasi Pokémon senza fallire. L'uomo che me l'ha data, [green]Aros[red], ha detto di sorvegliarla come se la mia vita ne dipendesse. Finché qualcuno non mi mostra un piccolo Pokémon viola,¶[green]Hoopa[red]. Aros ha detto che colui che controlla Hoopa è il Guardiano di Borrius e degno di questa Ball. Sei tu il Guardiano di Borrius, o solo l'ennesima peste?", 'scr_7B5F6E': 'Mel? Beh, è solo un tipo normale! Colpire lui o i suoi Pokémon con dei potenti Pokémon di tipo [green]Lotta[blue] è un buon modo per batterlo. Se te la senti di combattere, inizia scivolando giù dallo scivolo accanto a me! Ma assicurati prima di fare scorta di provviste. Non si può tornare indietro finché non raggiungi Mel.', 'scr_7B8B24': "La mia famiglia possiede Villa Tarmigan da generazioni. Anzi, i miei antenati furono responsabili della nascita stessa di Borgo Tarmigan! Per questo mi piace stare seduto qui fuori e osservare la città ogni tanto. Non startene lì a poltrire come me. Carpe diem!¶Cogli l'attimo!", 'scr_7B8E3A': "Fin dai tempi antichi, il mitico Pokémon Darkrai infesta questa città. Si dice che ogni notte, quando l'orologio batte l'una, esca per tormentare i sogni delle masse. Fai attenzione! Non cadere nel vuoto oscuro!", 'scr_7BB3FF': '[player], sei così forte perché stai sempre con i tuoi Pokémon? Sì! Deve essere per forza così! Yarrow proverà a fare come te!', 'scr_7BC13C': 'Beh, se Log ti ha fatto compilare questo, vediamo se grazie a ciò hai fatto progressi!', 'scr_7BD6A6': 'Grunt 1: [blue]Voglio sentirti piagnucolare! Ti faremo a pezzi così forte che non ti dimenticherai mai di noi! Il Granbull del Terrore!', 'scr_7BFC60': 'Sei tu! Quella peste spaccona di prima!¶Adesso non fai più tanto il duro, eh?¶Senza la polizia sei solo una patetica mezza calzetta!¶E i fifoni patetici devono piangere!', 'scr_7C0278': 'Avorio: [red]Ti do il benvenuto, [player]. Ti stavamo aspettando.', 'scr_7C1100': 'Hoo hah!¶Questa piccola peste mi ha trovato!¶Adesso le insegno io una bella lezione!', 'scr_7C127E': 'Battuto da una peste come te?', 'scr_7C1783': 'Piccola peste! Preparati ad affrontare gli orrori del Granbull del Terrore!¶…¶Suonava meglio nella mia testa…', 'scr_7C1D3C': "[black]G-Roughs: [blue]Ahahah! Buona fortuna!¶Quanto a te, piccola peste, te la sei cavata bene contro i miei scagnozzi.¶Ma scoprirai che io non sono affatto un debole!¶Vediamo un po' cosa sai fare!", 'scr_7C33A6': 'Mi spiace, oggi trasporto solo spedizioni locali.¶Se passi in un altro giorno della settimana, potrei avere souvenir di varie regioni da distribuire.', 'scr_1EDE847': 'Mi spiace, oggi trasporto solo spedizioni locali. Se passi in un altro giorno della settimana, potrei avere souvenir di varie regioni da distribuire.', 'scr_7C39E4': 'Che mani roventi che hai!¶Vuoi farle ardere di potere infuocato?¶Posso insegnare [green]Fuocopugno[blue] al tuo Pokémon per soli [green]2 [buffer1][blue]!', 'scr_7C3B5B': 'Ascolta bene.¶Quel truffatore laggiù estorce continuamente [green]Cocci Rossi[blue] ai giovani come te.¶Tieni, gliene ho rubati un paio dalla collezione, tutti per te.', 'scr_7C496B': 'Quando te la senti di sfidare Maxima, ti basta scendere dal bordo.¶Non preoccuparti, non ti farà male.', 'scr_7C5AB9': '[red]Non importa.¶Ho guadagnato abbastanza tempo perché tutti gli altri potessero fuggire.¶Comunque, bel tentativo.¶Prendi questo pacco come premio di consolazione.¶Ne abbiamo già preso ciò che ci serviva.', 'scr_7C7CF5': "Hoooo weeee! Se non è la cosa più strana che abbia mai visto! Un [buffer1] che esce da un portale magico! Da dove vieni, [buffer1]? … Come? Stavi cercando di raggiungere Monte Thundercap quando all'improvviso ti hanno rapito! Hoooo weeee! Sembra davvero spaventoso, [buffer1].", 'scr_7C7DFA': "Beh, se non ti avessero rapito, faresti molta meno fatica ad arrivare al Monte Thundercap.¶Vedi, parte del soffitto è crollata poco fa e ha bloccato la strada!¶E a meno che tu non abbia la MN di [green]Spaccaroccia[blue], sarà un bel pasticcio superare quei massi.¶Ma…¶Immagino che tu non ce l'abbia, altrimenti non staresti ancora parlando con me.¶In tal caso, un mio amico a [green]Città Bufera[blue] può aiutarti dandoti Spaccaroccia.¶Quindi, prendi questa MN per aiutarti ad arrivare da lui.", 'scr_7C8093': 'Mel: [blue]Questo è il tuo ultimo avvertimento. Spostati, o ti sposto io.', 'scr_7C88FD': "Hai mai visitato la SES Expressway?¶È un'autostrada sotterranea che gira tutt'intorno a Borrius.¶È un vero paradiso per chi viaggia con lo zaino in spalla!", 'scr_7CE0A5': 'Io e il mio Pokémon abbiamo corso per tutto Borrius.¶Battiamo chiunque, anche te!', 'scr_7CE574': "Beh, beh, beh… Ma guarda, c'è [player]!¶Il capo mi ha detto di non farti entrare sul Monte Thundercap, così non potrai intralciare i nostri piani.¶Anche se ti lasciassi entrare, non avresti scampo senza il potere della Megaevoluzione.¶Non lo capisci?¶Faresti bene a restare qui fuori, per il tuo bene.", 'scr_1F035CF': 'Bene, bene, bene… Ma guarda, [player]!¶Ciprian mi ha detto di non farti entrare nel Monte Thundercap, così non potrai intralciare i nostri piani.¶E anche se ti lasciassi entrare, senza il potere della [green]Megaevoluzione[blue] non avresti scampo.¶Non capisci?¶Per il tuo bene, dovresti restartene qui fuori.', 'scr_7D0111': '[blue]Oh! [player]!¶Arrivi proprio in tempo!', 'scr_7D2062': "Stai bene?¶Questo strano anello è apparso sotto di te, a Città di Dehara.¶Avevo paura che stesse per succedere qualcosa di brutto, così ti ho afferrato la maglietta prima che l'anello ti teletrasportasse via.¶Ma a quanto pare Bellocchio non ha avuto la stessa idea…", 'scr_7D36B5': "[blue]Grazie per aver trovato il mio Staraptor! Sono riuscito a curarlo in tempo, quindi sembra che starà bene. Complimenti, tra l'altro: hai fatto molta strada. Sembra che siamo quasi in cima. Un piano ancora più su, e riusciremo a fermare le Ombre. Ti lascio fare, allora. Se hai bisogno di cure, ti aspetterò all'ingresso laterale su questo piano delle rovine.", 'scr_7D43BF': 'Recluta 2: [blue]Muoviti, tu. Questo vorrai vederlo…', 'scr_7D6B7C': 'Recluta: [red]Signore! [player] è ancora in vita!', 'scr_7D6BD9': "Ciprian: [blue]Quindi ce l'hai fatta anche tu, [player]… Presto, aiutami a occuparmi di questi @qoattrezzi della¶Luce della Rovina@qc.", 'scr_7D8AE2': 'Ehi, ehi, attenzione! È pericoloso!', 'scr_7DA0FF': "Zefiro: [blue][player]!? Come fai a essere ancora in vita? Ti ho visto bruciare! All'inizio credevo che Ciprian mentisse, ma non ho scelta se non credergli ora che ho visto il tuo volto sotto quel cappuccio! La pagherai per i danni che hai causato! Tutto quello che è successo…era tutto colpa tua!", 'scr_7E7283': "Lascia che ti dica una cosa.¶A est di qui c'è un vasto deserto.¶È così straordinario che si chiama semplicemente [green]Grande Deserto[blue].¶Le parole non bastano nemmeno a descriverlo!¶Però è davvero difficile attraversarlo senza l'equipaggiamento adatto.¶Quindi non pensare di poterti avventurare là fuori senza prepararti prima.¶Il tuo abbigliamento sembra un po' troppo caldo per il deserto, ma proteggerà bene il tuo corpo.¶Per gli occhi, ti consiglio di procurarti un buon paio di [green]Occhialoni[blue].¶Anzi, sarei disposto a darti i miei se mi mostri quanta forza hai [green]battendo la Palestra[blue].", 'scr_1EFBE01': "Lascia che ti dica una cosa.¶A est di qui c'è un vasto deserto.¶È così straordinario che si chiama semplicemente [green]Grande Deserto[blue].¶Le parole non bastano nemmeno a descriverlo!¶Però è davvero difficile attraversarlo senza l'equipaggiamento adatto.¶Quindi non pensare di poterti avventurare là fuori senza prepararti prima.¶Il tuo abbigliamento sembra un po' troppo caldo per il deserto, ma proteggerà bene il tuo corpo.¶Per gli occhi, ti consiglio di procurarti un buon paio di [green]Occhialoni[blue].¶Anzi, sarei disposto a darti i miei se mi mostri quanta forza hai [green]battendo la Palestra[blue].", 'scr_7E74E0': 'Su, vai! Esplora il Grande Deserto!', 'scr_1EFC0C6': 'Su, vai! Esplora il Grande Deserto!', 'scr_7E8D4B': 'Ehi. … Cosa? Vuoi che dica qualcosa di interessante? Va bene allora… Ultimamente ho avuto dei problemi con mio fratello. Si è immischiato fino al collo con questa banda che si fa chiamare @qoEmboar Neri@qo. Non so bene di cosa si tratti, ma sono davvero preoccupato per la sua incolumità. Non gli parlo da giorni, quindi temo che gli sia successo qualcosa di brutto. … Cosa? Ti andrebbe di controllare come sta al posto mio?', 'scr_7E9072': '[blue]Ehi! Sì, tu, peste laggiù! Vieni qui!', 'scr_7E90AB': '[blue]Ehi! Chi ha detto che puoi passare di qui? Questo posto è nostro, degli Emboar Neri! È quasi la nostra Palestra, peste! Quindi fila! Tornatene a casa da mammà, piccola peste perbenista!', 'scr_7E91E6': '[blue]Che hai detto, brutta peste? Ti insegnerò a prendere sul serio gli Emboar Neri! Farò a pezzi i tuoi bei Pokémon e li stenderò al suolo! Con gusto!', 'scr_7E934E': 'Che credi di fare, peste? Questo è il paradiso supremo degli Emboar Neri… Un piccolo fastidio come te non ha niente da fare qui… Possibile che tu creda di potermi tener testa, io che sono il capo degli Emboar Neri?', 'scr_7E9734': 'Che vuoi? Siamo occupati!', 'scr_7E9872': 'Gwa ha ha ha! Vieni pure! Hai un bel fegato, eh! Ti mostrerò cosa sa fare davvero quello che tiene insieme gli Emboar Neri!', 'scr_7E9909': "Non sei niente male… Mi piaci. Ascolta un po'… Da ora in poi, il nome della nostra squadra sarà il Black [player]! Sì! Ci prendiamo il tuo nome rude e tosto!¶È un nome più selvaggio per una squadra più selvaggia! Il Black [player]! Gwa ha ha ha! È fantastico!", 'scr_7E99FB': 'Che vuoi ancora? … Mio fratello? Accidenti, quel teppista non molla mai. È ora che la faccia finita una volta per tutte con lui…', 'tbl_move_names_00069_A40D91': 'Mov. Sismico', 'tbl_move_names_00101_A40F31': 'Ombra Nott.', 'tbl_move_names_00478_A42256': 'Fiordifesa', 'tbl_move_names_00844_A434EC': 'Erbamax', 'tbl_move_names_00880_A436C0': 'Ripristino', 'tbl_move_names_00776_A43178': 'Mossa Z 10', 'tbl_move_names_00777_A43185': 'Mossa Z 11', 'tbl_move_names_00778_A43192': 'Mossa Z 12', 'tbl_move_names_00779_A4319F': 'Mossa Z 13', 'tbl_move_names_00780_A431AC': 'Mossa Z 14', 'tbl_item_names_00084_877070': 'Repell. Max', 'tbl_pokemon_names_00253_166B46B': 'MISSINGNO.', 'tbl_pokemon_names_00492_166BEB0': 'Mime Jr.', 'tbl_pokemon_names_00770_166CAA2': 'Fletchindr', 'tbl_pokemon_names_00957_166D2AB': 'Crabminble', 'tbl_pokemon_names_01077_166D7D3': 'Blacphalon', 'tbl_pokemon_names_01114_166D96A': 'Corvsquire', 'tbl_pokemon_names_01115_166D975': 'Corvknight', 'tbl_pokemon_names_01139_166DA7D': 'Baraskewda', 'tbl_pokemon_names_01143_166DAA9': 'Centskorch', 'tbl_pokemon_names_01147_166DAD5': 'Poltegeist', 'tbl_pokemon_names_01166_166DBA6': 'Stonjorner', 'tbl_pokemon_names_01195_166DCE5': 'Poltegeist', 'tbl_pokemon_names_01228_166DE50': 'Mime Jr.', 'tbl_pokemon_names_01254_166DF6E': 'Basculegon', 'tbl_pokemon_names_01255_166DF79': 'Basculegon', 'tbl_pokemon_names_01277_166E06B': 'Corvknight', 'tbl_pokemon_names_01286_166E0CE': 'Centskorch', 'tbl_move_names_00635_A42A4F': 'Truccodifesa', 'tbl_item_names_00203_8784E4': 'Sabbia Soff.', 'tbl_move_names_00820_A433B4': 'Barrimax', 'tbl_move_names_00821_A433C1': 'Normalmax', 'tbl_move_names_00822_A433CE': 'Normalmax', 'tbl_move_names_00823_A433DB': 'Pugnomax', 'tbl_move_names_00824_A433E8': 'Pugnomax', 'tbl_move_names_00825_A433F5': 'Aeromax', 'tbl_move_names_00826_A43402': 'Aeromax', 'tbl_move_names_00827_A4340F': 'Acidomax', 'tbl_move_names_00828_A4341C': 'Acidomax', 'tbl_move_names_00829_A43429': 'Sismamax', 'tbl_move_names_00830_A43436': 'Sismamax', 'tbl_move_names_00831_A43443': 'Rocciamax', 'tbl_move_names_00832_A43450': 'Rocciamax', 'tbl_move_names_00833_A4345D': 'Coleomax', 'tbl_move_names_00834_A4346A': 'Coleomax', 'tbl_move_names_00835_A43477': 'Spettromax', 'tbl_move_names_00836_A43484': 'Spettromax', 'tbl_move_names_00837_A43491': 'Acciaiomax', 'tbl_move_names_00838_A4349E': 'Acciaiomax', 'tbl_move_names_00839_A434AB': 'Fiammamax', 'tbl_move_names_00840_A434B8': 'Fiammamax', 'tbl_move_names_00841_A434C5': 'Idromax', 'tbl_move_names_00842_A434D2': 'Idromax', 'tbl_move_names_00843_A434DF': 'Erbamax', 'tbl_move_names_00845_A434F9': 'Elettromax', 'tbl_move_names_00846_A43506': 'Elettromax', 'tbl_move_names_00847_A43513': 'Psicomax', 'tbl_move_names_00848_A43520': 'Psicomax', 'tbl_move_names_00849_A4352D': 'Geliomax', 'tbl_move_names_00850_A4353A': 'Geliomax', 'tbl_move_names_00851_A43547': 'Dragomax', 'tbl_move_names_00852_A43554': 'Dragomax', 'tbl_move_names_00853_A43561': 'Buiomax', 'tbl_move_names_00854_A4356E': 'Buiomax', 'tbl_move_names_00855_A4357B': 'Fatamax', 'tbl_move_names_00856_A43588': 'Fatamax', 'tbl_battle_messages_00228_3FCB5F': '§@00 di @0F⏎[player]', 'tbl_battle_messages_00229_3FCB6A': '§@00 di @10⏎[player]', 'tbl_battle_messages_00231_3FCB8F': '§@00 di @0F⏎[player]', 'tbl_battle_messages_00232_3FCB9A': '§@00 di @10⏎[player]', 'tbl_battle_messages_00005_A4B2BF': '@16 di @13 cura il suo congelamento!', 'tbl_battle_messages_00007_A4B2F9': '@00 di @13 non è diminuita!', 'tbl_battle_messages_00096_3FBDC4': 'Ma Baraonda tiene sveglio @10!', 'tbl_battle_messages_00069_3FBB4C': '@10 è stretto da Avvolgibotta di @0F!', 'v7_096DCFD': 'Grazie al Potere Z, @00 di @13 [player]', 'tbl_move_learning_00007_41743F': 'PUÒ!', 'tbl_move_learning_00003_416E6B': 'Smettere di insegnare [buffer2]?', 'tbl_battle_messages_00000_A4B23C': '@11 soffre di congelamento!', 'tbl_battle_messages_00019_A4C915': 'congelamento', 'tbl_battle_messages_00008_906470': 'Il Curardore si è avverato per @13!', 'v7_08B6D90': '@0F è diventato Greninja di Ash!', 'tbl_battle_messages_00305_3FD2D9': 'Lo Spettro è apparso!¶Accidenti! Impossibile identificare lo Spettro!', 'tbl_battle_messages_00306_3FD30D': 'Lo Spettro è apparso!', 'tbl_battle_messages_00308_3FD34D': 'Lo Spettro era [rival]!', 'tbl_battle_messages_00124_3FC090': 'Attorno alla squadra avversaria sono state sparse delle punte!', 'tbl_battle_messages_00292_3FD186': 'La prossima scelta di @1D, @1C, sarà [player].¶@23, vuoi cambiare Pokémon?', 'tbl_battle_messages_00400_3FDAE2': "Log: Oh, per l'amor del cielo… Sempre così insistente.¶@23.¶Non hai mai fatto una lotta Pokémon, vero?¶In una lotta Pokémon gli Allenatori fanno combattere i loro Pokémon.", 'tbl_battle_messages_00401_3FDB92': "Vince l'Allenatore che manda KO i Pokémon dell'altro portandone i PS a @qo0,@qc", 'tbl_battle_messages_00402_3FDBEF': "Ma invece di parlarne, imparerai di più con l'esperienza.¶Prova a lottare e scoprilo di persona.", 'tbl_battle_messages_00405_3FDCD2': "Log: Tieni d'occhio i PS del tuo Pokémon.¶Andrà KO se i PS scendono a @qo0.@qc", 'tbl_battle_messages_00407_3FDD64': 'Log: Mh! Ottimo!¶Se vinci, ottieni denaro in premio e i tuoi Pokémon crescono!¶Lotta contro altri Allenatori e rendi forti i tuoi Pokémon!', 'tbl_battle_messages_00008_A4C6B3': 'Nel panico, hai perso $@00…¶… … … …¶La sconfitta ti ha travolto![pause]', 'tbl_battle_messages_00010_A4C740': 'Hai pagato $@00 come premio in denaro…¶… … … …¶La sconfitta ti ha travolto![pause]', 'tbl_battle_messages_00011_A4C790': 'La sconfitta ti ha travolto![pause]', 'tbl_battle_messages_00022_3FB484': '@23 non ha più Pokémon!¶Player perde contro @1C @1D![pause]', 'tbl_battle_messages_00023_3FB4BE': '@23 paga $@00 come premio…¶… … … …¶@23 è fuori gioco![pause]', 'scr_7C0350': 'Moglie: [red]Non farlo! Se lo consegni, saremo tutti perduti!', 'scr_7C16AC': "Borgo Epidimy è l'epitome della beatitudine!¶…¶…¶Cosa? Non lo trovi divertente? Scusa…¶Ora mi sento in colpa…¶Sai che c'è? Prendi queste. Mi aiuteranno a sentirmi meglio.", 'scr_7C1C05': 'Ottimo lavoro! Hai radunato tutti e quattro quegli scagnozzi di Granbull del Terrore.¶Tuttavia, il loro capo è ancora in fuga.¶Chissà dove sarà… Forse è tornato a Città di Antisis?', 'scr_7C1E8A': 'Grazie di tutto il tuo aiuto, [player].¶Avviserò via radio i miei colleghi di Città Portuale, così non potrà scappare di là.¶Comunque, ecco una ricompensa per una persona esemplare come te.', 'scr_7C23BD': 'Qui al Club degli Sciatori abbiamo un sacco di Gemme Ghiaccio.¶Si attaccano sempre sotto i nostri sci!', 'scr_7C27A4': 'Al ladro! Rimettilo a posto! È il mio bene più prezioso!', 'scr_7C4B3D': "Il Megacerchio ti permette di usare il potere della Megaevoluzione.¶Per attivarla, il Pokémon che lotta deve tenere la sua Megapietra.¶Per megaevolvere in lotta, quando vedi apparire il simbolo Mega, premi il pulsante Start.¶Il tuo Pokémon si megaevolverà e diventerà ancora più potente!¶Ricorda solo che puoi far megaevolvere un solo Pokémon per lotta.¶Gli effetti della Megaevoluzione svaniranno una volta finita la lotta, quindi scegli con attenzione.¶Ho fiducia che userai questo Megacerchio per il bene dell'umanità.¶Non deludermi, [player].¶Conto su di te per fare la differenza nel mondo.", 'scr_7C4D7E': 'Salve, Allenatore. Mi chiamo Successore Maxima.¶Superare la mia villa non è impresa da poco.¶Ci sono così tante salite e discese che persino io a volte mi perdo!¶Ma alla fine torno sempre quaggiù.¶Hai lottato duramente per arrivare fin qui, e questo è encomiabile.¶Ho ragione a supporre che tu sia qui in cerca del potere della Megaevoluzione?¶………¶………¶Capisco…', 'scr_7C6014': 'Come? Dici che mia figlia è stata portata via da un forte vento?¶Non può essere andata lontano!¶Venti forti come quelli non bastano a portare una bambina fuori dai confini della città.¶Ti prego, continua a cercarla!', 'scr_7C6482': 'Sniff…¶La mia mamma mi ha lasciata qui tutta sola…¶Non credo che le importi più di me…', 'scr_7C6692': 'Sono…così…stordita…', 'scr_7C66A0': 'Mamma! Mi hai trovata!¶Mi sei mancata tantissimo! Avevo così paura…¶Questo ventaccio mi faceva volare da tutte le parti!¶Ma adesso sto bene, grazie a questa persona!', 'scr_7C7C9C': 'Zefiro: [blue]Reclute!¶Prendete [buffer1] subito, prima che [buffer2] scappi!', 'scr_7C80C9': 'Recluta: [blue]Mi rifiuto di abbandonare il mio posto.¶Devo impedire a [player] di entrare nel Monte Thundercap a qualsiasi costo.', 'scr_7C82C6': 'ALT!', 'scr_7C8844': 'Avorio: [red]Incenerisci anche lei, Houndoom.¶Non ci serve più.', 'scr_7C90A4': "Ciprian: [blue]L'ha semplicemente disintegrato…", 'scr_7C90CA': '[blue]Tutte le reclute e i Guerrieri Ombra rimasti, trattenete Zapdos!', 'scr_7C9B04': "Non smetti mai di stupirmi, [player].¶Ma accetta un consiglio: non seguirmi.¶Se tieni il naso fuori dagli affari degli altri, non ti farai male.¶Meglio stare al sicuro che cercare di fare l'eroe…", 'scr_7CE767': '[player] ha ricevuto il Megacerchio da Successore Maxima!', 'scr_7CEB3E': 'Cosa stai dicendo, [player]?¶Vedo benissimo quel Megacerchio al tuo dito!¶Forse è che non sai come usare la Megaevoluzione?¶Beh, prima devi essere in grado di lottare così!', 'scr_7CF1B6': "Mi dispiace!¶Una lotta tra alcuni Zangoose e Seviper ha distrutto il ponte.¶Ci vorrà un po' prima che lo ripariamo.¶Nel frattempo dovresti parlare con il nostro capo per trovare un percorso alternativo per Città Portuale.", 'scr_7CF8D5': "[blue]Non abbiamo più tempo da perdere, Hoopa.¶So che non volevo arrivare a questo, ma ho bisogno che tu mi mandi alle Rovine del Vuoto attraverso uno dei tuoi anelli.¶Andrò avanti io e, dato che non puoi viaggiare attraverso i tuoi stessi anelli senza un legame, agganciati al segnale del mio Cubo quando sarò arrivato.¶Cerca solo di non dare nell'occhio, per favore.¶Non posso permettere che Zefiro scopra il nostro piano.¶Non metterci troppo, Hoopa.", 'scr_7D049A': 'Jax: [blue]Che succede?¶[player]! Attenzione!', 'scr_7D31E5': 'Recluta 1: [blue]Non abbiamo niente da dimostrare!¶Siamo le Ombre!¶Abbattiamolo!', 'scr_7D397F': "Recluta 1: [blue]Quel Claydol ci avrà anche messi fuori combattimento per un po', ma non ti lasceremo comunque passare senza combattere!¶La liberazione non deve essere interrotta!", 'scr_7D3A41': 'Recluta 2: [blue]Non abbiamo ancora finito!¶Tocca a me farti fuori!', 'scr_7D3B16': '[blue][player]!¶Mi occupo io di questi manigoldi.¶Tu vai a impedire alle Ombre di portare a termine la loro @qoliberazione@qc.¶Contiamo su di te.', 'scr_7D439A': "Recluta 1: [red]C'è chi non impara mai…", 'scr_7D473C': '[blue]Con questi tre Pokémon uccello leggendari riuniti qui insieme alla Pietra del Vuoto, il sigillo può essere spezzato.', 'scr_7D4959': "???: [blue]Io? Mi chiamo Aklove.¶Sono solo un'umile recluta delle Ombre.", 'scr_7D4D87': 'Zefiro: [blue]Non è possibile…¶Il mio Houndoom…¶Quindi eri tu a salvare [player] tutte quelle volte…', 'scr_1EE15CC': '[blue]Un Pokémon che tiene il [green]Darkinium Z[blue] potenzia i suoi attacchi di tipo [green]Buio[blue], per aumentare la propria forza o per sferrare un colpo devastante.¶Tuttavia può prosciugare le energie del suo Allenatore, quindi è meglio usarlo una sola volta per lotta.¶[green]Eclissi del Buco Nero[blue]…¶Mi ricorda molto un collega agente che conoscevo un tempo.¶Indossava così tanti travestimenti che alla fine dimenticò il suo vero nome e il suo vero volto… e divenne simile a un abisso senza fondo…', 'scr_1EE1B37': "[player]! Ma che incontro fortunato!¶Guardati! Hai conquistato il titolo di Campione di Borrius!¶Hai raggiunto vette che nemmeno io ho osato sfiorare!¶E mi sono chiesta… che venti hanno soffiato dalla tua parte, per portarti fino in cima?¶Be', mi è appena venuta un'idea fantastica.¶Cerco un'altra lotta.¶Voglio vedere quali venti hai cavalcato fino alla gloria.¶È stata davvero fortuna… o hai un talento tale da piegare il caso stesso?¶Allora? Ti va un'altra lotta?", 'scr_1EE1E1C': "[red]Ah… e così è andata a finire?¶È stato d'ispirazione. Davvero.¶Che sia stato il caso o l'abilità… poco importa.¶Mi ha emozionato comunque.¶Tieni, è tuo.¶Forse questo Cristallo Z potrà ribaltare la prossima lotta… proprio così.", 'scr_1EE1F1E': '[red]Il [green]Cristallo Z Volante[red] trasforma una mossa di tipo [green]Volante[red] in una potente [green]Mossa Z[red].¶Ricorda però che le Mosse Z si possono usare solo una volta per lotta.¶Tienilo a mente.¶Più alta è la salita, più dolorosa è la caduta…¶Come ogni Pokémon sa bene dopo un bel [green]Colpo Celeste Supersonico[red]!', 'scr_1EE203B': "[player]! Quindi oggi sei qui anche tu…¶Mi è tornata voglia di lottare, così sono tornata per riprovarci!¶Non mi importa quanto ci vorrà, quante volte dovrò cadere…¶Mi basta cogliere un solo, unico momento.¶Sei d'accordo, vero?", 'scr_1EE22C9': "Be', guarda un po'…¶Ma è proprio [player]!¶Direi che tutto quel trambusto dopo il Monte Thundercap è finito bene, eh?¶Da allora… hai qualcosa di diverso.¶Nah, non parlo di bellezza…¶Nessuno è più affascinante del vecchio Mel.¶Voglio dire che hai l'aria più rilassata.¶Ricordo che nella mia Palestra avevi i nervi tesi come un lazo.¶A dire il vero… già che siamo qui… che ne dici di una rivincita con questo bel fusto?¶Voglio vedere come lotti davvero, senza distrazioni a frenarti.¶Che ne dici? Un altro rodeo?", 'scr_1EE24C3': 'Beh… non me ne vado da nessuna parte fino a domani.¶Se cambi idea… sarò proprio qui.', 'scr_1EE2521': "Così mi piace! Io intanto me ne vado con calma verso l'area lotta, va bene?", 'scr_1EE26E8': '[green]Normalium Z[blue]… è semplice, ma quando lo attivi, gli attacchi di tipo [green]Normale[blue] diventano [green]Mosse Z[blue].¶Vale solo una volta per lotta, però: di più e ti sfiniresti.¶Di solito nessuno subisce danni extra dagli attacchi di tipo Normale, ed è per questo che preferisco le Lotte Inverse.¶[green]Assalto Travolgente[blue]…¶Viene spesso messa in ombra dalle altre Mosse Z, ma sono sicuro che le troverai un uso!', 'scr_1EE2DB1': "Ah, sei un mito!¶E visto che sei un mito, facciamo la nostra lotta come [green]Lotta in Doppio[blue]!¶Forza, ti sfido a chi arriva prima all'area lotta!", 'scr_1EE2F9F': '[green]Steelium Z[blue], [green]Electrium Z[blue]… questi due cristalli potenziano al massimo gli attacchi di tipo [green]Acciaio[blue] ed [green]Elettro[blue].¶Peccato che non si possano usare tutti e due nella stessa lotta, ma la vita a volte non è giusta.¶A dire il vero, non so proprio decidere quale sia meglio per mettere a soqquadro il campo.¶Spalmarli sul pavimento con [green]Schianto a Cavatappi[blue]…¶O lasciarli a terra tutti tremanti con una bella [green]Scarica Gigavolt[blue]?¶Sono fantastici tutti e due!', 'scr_1EE32DA': "Tra gli Allenatori di tipo Elettro c'è uno stereotipo…¶Pare che bisogni essere bravi con le macchine anche solo per allenarli come si deve.¶Voglio dire, il vecchio Galvani non crede alle etichette, ma capisco il perché.¶Hai VISTO che danni fanno alla nostra tecnologia?¶Andremmo in rovina se non riparassimo da soli quello che rompono!¶Ah ah ah ah!", 'scr_1EE3416': "Ah ah ah ah! Guarda chi si è fatto vivo!¶Ma è [player], fresco di titolo di Campione!¶Hah! Se sei qui, vuol dire che hai già messo le mani su questo territorio, eh?¶L'ultima volta che ho perso, ho capito che dovevo andarmene e… diciamo, farmi valere altrove, mi spiego?¶Ma mi sa che devo continuare a cercare la nuova base di Gran Mo, eh?¶A meno che… tu non voglia sfidare il boss, qui e ora?¶Sul serio stavolta. Il locale va a chi vince.¶Ti avverto, non sono più quello di prima!¶Allora? Che si fa, fenomeno? O tremi già come una foglia?", 'scr_1EE3641': "Grr… Mi stai guardando dall'alto in basso, faccia da schiaffi?¶Bene, io resto qui finché non mi cacci, chiaro?¶…o fino a domani. Ho altro da fare.", 'scr_1EE3716': '[blue]Sei in trappola in questa gabbia con me, e non hai via di fuga, mezza calzetta!', 'scr_1EE38B9': "[blue]È il [green]Lottium Z[blue]!¶Con quello gli attacchi di tipo [green]Lotta[blue] diventano mostruosi!¶Però sono sfiancanti.¶Io sono Gran Mo, e perfino io posso farlo una sola volta per lotta!¶Ma in quell'unico istante in cui attingo al Cristallo Z…¶Qualsiasi poveraccio che si trova in mezzo si becca una [green]Percossa Totale[blue]!¶Senza esclusione di colpi!", 'scr_1EE3C49': "Ehilà, tesoro! Che sorpresa trovarti qui!¶Dopo la nostra lotta in Palestra ero in pensiero per te, ma non ce n'era bisogno!¶Io? Be'… anche a me serve staccare un po' dalla palude, schiarirmi le idee, capisci?¶E poi dicono che qui si radunino i migliori di tutta Borrius.¶Dev'essere vero, se ci sei tu.¶Allora, visto che ammazziamo il tempo entrambi… ti va un altro round? Io e te?¶L'ultima volta sembravi… con l'acqua alla gola, come se la mia Medaglia fosse questione di vita o di morte.¶Stavolta voglio affrontare [player] per com'è davvero.¶Che ne dici? Non vedo l'ora di farti vedere quanto siamo migliorati anche noi!", 'scr_1EE3E82': 'Hai troppo da fare? Capisco. Comunque, sono qui tutto il giorno, quindi se cambi idea… ripassa pure.', 'scr_1EE3F1D': '[red]Sei già nei guai fino al collo… e andrà solo peggio! Preparati!', 'scr_1EE409A': '[red]Usa il [green]Waterium Z[red], e trasformerà qualsiasi attacco di tipo [green]Acqua[red] in una potente [green]Mossa Z[red]!¶Ma vale una volta sola per lotta, quindi fai in modo che il colpo vada a segno.¶A vedere una mossa come [green]Idrovortice[red]…¶Meno male che la palude non patisce roba del genere!¶Voglio dire, ultimamente di problemi ne ha già avuti abbastanza…', 'scr_1EE42C4': '[red]Accidenti. Sei molto più forte di quanto pensassi, tesoro.¶Tieni, questo è per te.¶Consideralo una promessa: ci sfideremo di nuovo!', 'scr_1EE4343': 'Chissà come se la passa Mel?¶Ha sempre fatto fatica a lasciar andare le cose.¶Regali, il suo passato, perfino i rancori… li tiene stretti.¶Non si nota, a meno che non ci si faccia caso.¶Quando mi sono trasferita a Polder ho cercato di lasciarci in buoni rapporti: gli ho affidato perfino la mia vecchia Palestra.¶Se capitasse qui lo stesso giorno in cui ci sono io… chissà cosa direbbe… o se direbbe qualcosa?', 'scr_1EE4804': "Ah, ti ringrazio. Allora mi dirigerò verso l'area lotta.", 'scr_1EE488F': 'Oh oh oh oh… non smetti mai di stupire, come sempre.', 'scr_1EE49B2': '[blue]Il [green]Buginium Z[blue] potenzia gli attacchi di tipo [green]Coleottero[blue], come avrai intuito.¶Scatena una potente [green]Mossa Z[blue], ma questo asso nella manica si può usare una sola volta per lotta.¶Ho scoperto di avere un debole per il risultato, la letale [green]Rotazione Selvaggia[blue].¶Il mio vecchio maestro la usava con gli allievi che non sapevano distinguere un bozzolo da una crisalide…¶A proposito, il bozzolo è una struttura di seta fatta per ospitare una creatura.¶La crisalide È la creatura.', 'scr_1EE4CC1': '[blue]Ah… vedere quanto è forte la nuova generazione di Allenatori mi fa sempre sorridere.¶Riesci sempre a farmi sentire - e sembrare - più giovane.¶Per questo, credo che questo spetti a te.', 'scr_1EE4FDC': 'Nella lotta contro la Capopalestra Alice, un [green]Ventoincoda[blue] soffierà alle spalle di tutti i Pokémon di tipo Volante, oltre a [green]indebolire gli attacchi superefficaci[blue] contro di loro!', 'scr_1EE5371': 'Nella lotta contro la Capopalestra Tessy, ci sarà una [green]pioggia intensa[blue] e i Pokémon assumeranno i [green]tipi[blue] delle loro [green]prime due mosse[blue]!', 'scr_1EE590F': 'Oh… capisco. Speravo che dicessi di sì…¶Victini ne combina di tutti i colori, perché con me è sempre insoddisfatto.', 'scr_1EE597F': "Oh, grazie mille!¶Victini e io resteremo qui per un po'.¶Devi solo farci vedere le tue splendide vittorie qui al Campo di Lotta…¶Ma non basta…¶Credo che, per accontentare davvero Victini…¶Tu debba completare l'intera [green]Sfida Classica dei Capipalestra[red].¶Batti tutti e otto i Capipalestra di Borrius, come solo il Campione della nostra regione sa fare!", 'scr_1EE5BDA': 'Oh, il tuo splendore… era davvero fuori dal comune!¶Brillava così tanto, eppure né Victini né io abbiamo mai osato distogliere lo sguardo!¶Allora è deciso!', 'scr_1EE6082': 'Per favore, non mi disturbare. Sono in servizio.', 'scr_1EE60B2': 'Come, scusa? Un pacco rubato?¶Lascerò che se ne occupino i Pokémon Ranger.¶Sono in servizio.', 'scr_1EE63D8': 'Lo sapevi che esiste una speciale Poké Ball che cura i Pokémon?¶Quando catturi un Pokémon, tutti i danni subiti vengono annullati!¶Forse, se avessi un [green]Pokédex[blue], sarei più propenso a dartene qualcuna!', 'scr_1EE6521': 'Usale in buona salute! Eh, eh, hai capito il gioco di parole?', 'scr_1EE65F3': 'Lo sapevi che esiste una speciale Poké Ball che può catturare Pokémon di altri mondi che a volte compaiono allo stato selvatico?¶Tieni, prova!', 'scr_1EE6B5A': 'Va bene, allora il tuo compleanno è il [buffer1]/[buffer2]/[buffer3].¶Questo significa che oggi compi @07 anni! Buon compleanno!', 'scr_1EE70FC': 'È mio compito accogliere i viaggiatori stanchi che salgono a piedi fino a Città Bufera.¶Prendere la Superstrada KBT è facile, ma salire a piedi… quella sì che è dura.', 'scr_1EE71F5': "Ah, [player]!¶Che piacere vederti da queste parti.¶Hai mai sentito un detto che piaceva tanto a mia nonna?¶@qoSe gli umani fossero destinati a volare, avremmo ali come un Gligar e piume come un Pidgeotto.@qc¶Beh, la prima parte credo di averla sistemata, ma… potrei avere bisogno di un aiutino per la seconda.¶Allora, se hai un po' di tempo oggi, daresti una mano a una simpatica signora?", 'scr_1EE811F': "Oh! Hai proprio quel tipo! Mi è venuta l'ispirazione!¶Grazie! Come segno della mia gratitudine, ti andrebbe una Bacca?", 'scr_1EE8184': 'Una [buffer1]! Ora è tutta tua!', 'scr_1EE81A0': '[buffer2] [buffer1]! Ora sono tutte tue!', 'scr_1EE81BE': 'Aww. Sei un tesoro! Torna anche domani, per favore!', 'scr_1EE8259': 'Baccaliegia', 'scr_1EE827E': 'Baccafrago', 'scr_1EE828A': 'Baccaperina', 'scr_1EE8297': 'Baccamela', 'scr_1EE8AD5': '[red]La mia mamma impazzirà di gioia quando vedrà il mio nuovo Pokémon!', 'scr_1EE926A': 'Il DexNav è un dispositivo complicato.¶Puoi chiedermi spiegazioni ogni volta che ne avrai bisogno.', 'scr_1EE9C12': "I Pokémon possono essere registrati per la ricerca premendo \\btn03 mentre l'interfaccia è aperta.¶Se un Pokémon è registrato e la [green]modalità del tasto R[blue] è impostata su [green]Scansione DexNav[blue], premere \\btn03 fuori dalla lotta consentirà una ricerca immediata del Pokémon, a patto che compaia nell'area.", 'scr_1EE5DC4': 'Ciao.¶Per caso, ti piacerebbe avere un [green][buffer1][blue]?¶È nato da un Uovo che ho fatto schiudere, ma non ho modo di allenarlo.', 'scr_1F602A0': 'Il mio Pokémon non conosce Turbosabbia, ma posso sempre dare una mano usando le mie abilità psichiche!', 'scr_1F63FFD': 'Il giorno delle gambe dovrebbe davvero essere una festa nazionale.', 'scr_1F5FD02': 'Eh? Come dici? Dici che qui non ci sono Pokémon Coleottero?', 'scr_1F5FD42': 'Eh? Come dici? Allora da dove avrei preso i miei Pokémon Coleottero?', 'scr_1F607C1': 'Vai verso la Via Vittoria, eh? Lascia che metta fine ai tuoi piani.', 'scr_1F6095F': "Come un vero membro della famiglia reale, ce l'hai fatta!¶Hai sconfitto tutti gli Allenatori qui sul Percorso 18!¶E da sovrana anch'io non posso che sfidarti di persona!", 'scr_1F61526': 'Gloria a [player]! Nessun Campione di Borrius è mai stato così grande!', 'scr_1F61BF2': "Ehi, tu! Ascolta. La strada più avanti è piena di Allenatori che vogliono combattere. Alcuni l'hanno persino soprannominata @qoChallenge Road@qc. Ma ehi, capisco se non vuoi affrontarli. Quindi, usando i miei incredibili poteri psichici, posso teletrasportarti dall'altra parte gratis! Che ne dici, ci stai?", 'scr_1F61DF9': 'Lo immaginavo! Si vede che in te arde una passione infuocata. Ebbene, qui ho questo Pokémon. Sarebbe perfetto per un Allenatore come te. Perché non sconfiggi tutti gli Allenatori sulla Challenge Road e poi torni qui? Te lo darò allora, quindi assicurati di avere spazio in squadra!', 'scr_1F61F20': 'Lo immaginavo! Si vede che in te arde una passione infuocata. Beh, dato che hai sconfitto tutti gli Allenatori su questa strada, direi che questo Pokémon te lo meriti.', 'scr_1F6205F': 'Oh, ecco chi arde di una passione infuocata! Scommetto che il [buffer1] che ti ho dato prima se la passa alla grande, eh?', 'scr_1F62D75': 'Hai dimostrato di valere più di tutti!', 'scr_1F6581A': 'Ehi, tu, vieni qui un attimo. Stai lentamente cadendo in un sonno profondo… Stai scivolando via… … Dannazione! Non sta funzionando! Dovrò metterti KO alla vecchia maniera!', 'scr_1F656E4': 'Però non sono ancora molto abile.', 'scr_1F5F82B': 'Cerco di non allontanarmi da qui, così la mia catena di pesca si allungherà il più possibile.', 'scr_1F5FFCE': 'Pur nuotando da quando ero in fasce, non avevo mai visto un Allenatore cavalcare sulla schiena di un Pokémon prima di affrontarti. Su quale Pokémon stai usando Surf, comunque? È un Wailmer? Sembra proprio di sì!', 'scr_1F6482E': 'A meno che tu non sappia usare Surf, andare da questa parte porta solo a un vicolo cieco.', 'scr_1F5F5A3': 'Che peccato. È proprio una sfortuna.', 'scr_1F60755': 'Non come te: tu sei soffice…', 'scr_1F608F4': 'La Via Vittoria non è per i deboli di cuore. Chi vi entra deve superare il famigerato e torturante… rompicapo di ghiaccio…', 'scr_1F61A0A': 'Come dici?¶Uno come me non è il tipo che sfida la Lega Pokémon?¶Accetto la scommessa!¶Un giorno mi vedrai nella stanza del Campione!¶Te lo garantisco!', 'scr_1F626E1': 'Purché perda insieme a Chad, il risultato non mi importa!', 'scr_1F62B63': 'Quella Megapietra è per [green]Lopunny[blue]!¶Quando megaevolve, abbraccia la sua vera natura e diventa anche di tipo Lotta!', 'scr_1F641BC': 'Pronti a partire… Più che altro, cotti a puntino!', 'scr_1F652CC': 'Sono così strani… Chissà perché sono diversi?', 'scr_1F65512': "Si vede che l'hai fatto!", 'scr_1F6569D': '[red]Il mio potere psichico consiste nel leggere la tua mente per imitare la tua strategia!', 'scr_1F65C0E': 'Grandioso! Mi piace il tuo stile.¶Penso che potremmo diventare amici.¶Prendi questa e vai a pescare!', 'scr_1F65D25': 'Ciao! I tuoi Pokémon sembrano stanchi. Lascia che li curi per te.', 'scr_1F660BD': 'Hai fatto solo [green][buffer2][blue] salti@07 senza subire danni da caduta. Te ne servono ancora almeno [green][buffer3][blue] per padroneggiare la tecnica.', 'scr_1F6612F': "Wow, ora padroneggi l'arte di saltare da altezze moderate senza danni da caduta! Ti stupirebbe sapere quanti Allenatori si fanno un po' male su quelle cose. Comunque, ecco un po' di Proteina come spuntino post-allenamento.", 'scr_1F6607D': 'Spero che un giorno vorrai padroneggiare questa abilità super segreta.', 'scr_1F67663': 'Accidenti! Tua madre non ti ha insegnato le buone maniere!?', 'scr_1F67C43': 'Ti aspetta una bella scossa! Ho appena richiamato tutte le reclute di guardia al varco, quindi ora siamo dappertutto su questo percorso!', 'scr_1F680C3': "L'INTERRUTTORE QUI SOTTO, POI EVITARE I DUSCLOPS: È QUESTA LA CHIAVE.", 'scr_1F6836D': '[buffer2] ha mangiato [buffer3].', 'scr_1F685B6': "Ti chiameremo con l'altoparlante quando finirai le Safari Ball. Puoi anche uscire quando vuoi premendo \\btn01. Se in qualsiasi momento vuoi scappare solo dal Pokémon attuale, ti costerà qualche Safari Ball. Beh, ti auguro buona fortuna!", 'scr_1F686DC': 'Scusa! I Box PC sono pieni.', 'scr_1F68723': 'Il tuo record attuale al Gioco Safari è di [green][buffer1][blue] Pokémon catturati.', 'scr_1F6876B': 'Al momento non hai ancora un record per il Gioco Safari.', 'scr_1F68919': "Mi dispiace!¶Non hai salvato prima di abbandonare la tua sfida l'ultima volta.¶Per questo, se oggi vuoi giocare al Gioco Safari, pagherai lo stesso prezzo di chi ha già giocato.¶Ti aspettiamo di nuovo!", 'scr_1F691C7': 'Più lunga è la tua serie di catture nel Gioco Safari, maggiori sono le probabilità che tu catturi qualcosa con buone statistiche!¶Ho persino sentito dire che appare un Pokémon cromatico ogni [green]30[red] incontri…', 'scr_1F69525': 'Come butta?¶Sono venuta fin qui da [green]Borgo Magnolia[red], a Borrius Orientale, per vedere questo famoso [green]Parco Lotta[red]!¶Ho sentito che si può passare ore a lottare senza sosta!', 'scr_1F69E3F': 'Allora non sei tu la persona che stavo aspettando…', 'scr_1F69F85': 'Ohé! Tu devi essere [player].¶I tuoi amici sono già saliti sulla barca per Borgo Polder.¶Mancavi solo tu, quindi salperemo subito.', 'scr_1F6A4F1': "Non c'è dubbio: il titolo di Campione ti spetta davvero!¶Ti prego, accetta questo compenso per il servizio reso alla polizia.", 'scr_1F6AFBD': 'Una donna non ha molto appetito ultimamente. Portale un Pokémon con un grande naso e i baffi per tirarla su di morale!', 'scr_1F6B3DF': 'Oh… Sono così sazia…', 'scr_1F6B3F0': 'Il mio lavoro mi tiene sempre molto occupato, quindi sono felicissimo se riesco a tornare a casa la sera. Mi dispiace lasciare mia moglie da sola, ma questa è la vita di un dirigente di alto livello. Oh, questo è un souvenir di un viaggio di lavoro. Lei non sembra averne bisogno, quindi lo darò a te.', 'scr_1F6B771': 'Forse non hai a cuore i Pokémon quanto pensavo.', 'scr_1F6B7E0': 'Non voglio darli via troppo in fretta… Torna quando avrai [green][buffer1] Medaglie[red], e te ne darò un altro.', 'scr_1F6B9CA': 'Tsk. Misura solo [buffer2] pollici. Il Pumpkaboo di prima era più grande. Misurava [green][buffer3][red] pollici, il Pumpkaboo più grande che mi hai portato.', 'scr_1F6BD78': 'Il proprietario di questa residenza ama stare seduto al piano di sotto. È piuttosto allegro da quando si è trasferito un nuovo inquilino.', 'scr_1F6C3C2': "Il tuo Pichu e il mio Pichu sembrano andare d'accordo alla grande! Si vede che con te sarà in ottime mani!", 'scr_1F6C8B6': 'Il tuo [green][buffer1][red] è cresciuto molto! Vediamo… In base al livello, è cresciuto di [green][buffer2][red]! Non sono brava in questo?', 'scr_1F6D2A1': "Sembra che questo albero si possa abbattere! Vuoi usare l'ADM?", 'scr_1F6DDCB': 'Vuoi una [green][buffer2][red]?', 'scr_1F6DE6E': 'Non hai abbastanza Cocci per la [green][buffer2][red].¶Ti servono: [green]@0C', 'scr_1F6DEB2': 'Lastradrakon', 'scr_1F6DEBE': 'Lastratimore', 'scr_1F6DECA': 'Lastrageo', 'scr_1F6DED6': 'Lastrapugno', 'scr_1F6DEE1': 'Lastrarogo', 'scr_1F6DEFA': 'Lastrabaco', 'scr_1F6DF07': 'Lastraferro', 'scr_1F6DF1F': 'Lastramente', 'scr_1F6DF2A': 'Lastraspiritello', 'scr_1F6DF36': 'Lastracielo', 'scr_1F6DF4D': 'Lastratetra', 'scr_1F6DF5A': 'Lastrapietra', 'scr_1F6DF66': 'Lastrafiele', 'scr_1F6DF72': 'Lastrasaetta', 'scr_1F6E312': 'Okay! Mancavi solo tu, allora.', 'scr_1F6E716': 'Ooh hoo hoo hoo! Ci hai trovati tutti, noi pagliacci! Pensare che qualcuno ci abbia trovati tutti… Devi avere davvero il dominio del clima! Per questo, hai la mia gratitudine.', 'scr_1F6F2FE': '[buffer1] è triste.', 'scr_1F6F30D': 'Eh? Sembra che [green][buffer1][black] voglia uscire dalla sua Poké Ball e camminare con te! Far uscire [green][buffer1][black]?', 'scr_1F70306': 'Ah, già… Ti andrebbe di fare una lotta con me, se hai tempo? A mio figlio sembrano piacere parecchio le lotte Pokémon, dopotutto.', 'scr_1F706E8': 'Grazie ancora per quella lotta. Anche se ho perso di nuovo, purché mio figlio sia felice, è tutto ciò che conta davvero per me. Torna pure un altro giorno, se vuoi sfidarmi di nuovo.', 'scr_1F707AF': 'Wow! Sei tu che hai aiutato mio papà a riportarmi indietro dal posto buio! Che forza!', 'scr_1F70BB2': "È una statua del Pokémon leggendario di tipo Fuoco, Moltres. Qui c'è scritto che un tempo Moltres veniva usato per rafforzare un sigillo su una grande oscurità, ma ora risiede nel Vulcano delle Ceneri.", 'scr_1F715A3': 'Locanda Tarmigan… Il testo è troppo sbiadito per essere letto.', 'scr_1F71945': 'Addestramento Guerrieri Ombra', 'scr_1F718E3': "C'è qualcosa scarabocchiato sul muro. @qoSala Sviluppo di Unbound@qc Non potevano permettersi un cartello?", 'scr_1F7252D': "Via Vittoria¶L'ultima sfida prima della Lega Pokémon.", 'scr_1F7257A': '§Foresta Redwood¶\\adCube Corp.', 'scr_1F72595': '§Foresta Redwood¶\\auVillaggio Redwood', 'scr_1F723A5': 'Borgo Magnolia¶La cittadina dei ranch con la splendida brezza marina.', 'scr_1FA6CEC': 'Fermi, ragazzi! Quella faccia mi sembra terribilmente familiare…¶Aspetta, ti conosco…@CC0820 sei quella peste che si è immischiata nei nostri affari sul Percorso 10!¶E da quello che ho sentito, hai dato fastidio anche ai miei ragazzi nella Palude Cootes, vero?¶Ed eccoti di nuovo qui.¶Ma si può sapere che problema hai, peste!?¶Ragazzi! Occhio a quella peste!¶Non sottovalutate[buffer2], o vi stenderà prima ancora che riusciate a dire @qoGranbull@qc!', 'scr_1FA85D0': '[blue]Non te la faremo passare liscia, grassone!¶Aspetta e vedrai… tu e la tua Skitty ve ne pentirete!', 'scr_1FA847A': '[blue]Nooooooooo! Brutti delinquenti! Lasciate stare la mia regina!', 'scr_1FA53FA': 'Papà ha allenato tanto il nostro Pokémon! Ora è davvero forte!', 'scr_1FA54AC': 'Il Pokémon sembra dirigersi verso la [green]Grotta Ghiacciata[black].', 'scr_1FA6C7C': 'Tornate qui, vacche stupide! Non avevo ancora finito di mungervi!', 'scr_1FA793C': 'Salve, giovane. Negli ultimi anni della mia vita sono riuscito a perdere al gioco tutti i miei soldi e i miei averi.¶Perciò ogni notte, con il sole o con la pioggia, dormo su una panchina.¶Sarebbe bello avere di nuovo un posto da chiamare casa…¶Senti…¶Sembri una persona piena di grinta. Ti andrebbe di trovarmi una casa? Fa un figurone su un curriculum.', 'scr_1FA7A6C': 'Che anima benedetta. Attenderò il tuo ritorno.', 'scr_1FA7AA0': 'Evidentemente mi sbagliavo su di te. Nessun giovane di buon cuore rifiuterebbe una richiesta simile da parte di un vecchio.', 'scr_1FA7BF6': 'Salve di nuovo, giovane. Mi sono sistemato piuttosto bene, grazie ai tuoi sforzi.¶Per favore, accetta questo raro cristallo come ringraziamento.', 'scr_1FA7C7D': 'Salve di nuovo, giovane. Sei molto gentile a venire a trovare questo buon vecchietto.', 'scr_1FA8182': 'Per favore, riportaci a casa sani e salvi, me e la mia regina…', 'scr_1FA81AB': 'Ah, sì. Credo che prima tu abbia menzionato qualcosa riguardo a un alloggio per un anziano signore?¶In tal caso, per ringraziarti, puoi pure dirgli che può trasferirsi al piano di sopra, gratis.', 'scr_1FA826A': 'Puoi pure far sapere al tuo amico che può trasferirsi di sopra, gratuitamente.', 'scr_1FA840E': '[blue]Dai, amico… Sbrigati a catturarla! Una Skitty come quella frutterà un sacco di soldi al Mercato Nero!', 'scr_1FA84AD': '[blue]Eh? E tu chi saresti? Pensi di poterti intromettere nei nostri affari?', 'scr_1FA84F4': "[blue]Qualcuno dovrebbe proprio insegnarti un po' di buone maniere!", 'scr_1FA878E': '[blue]Ve la siete meritata, tu e lui.¶Se vuoi rivedere quel tizio snob, presentati senza nessuno al [green]magazzino occidentale[blue].¶E non portare Pokémon che non siano di tipo [green]Ghiaccio[blue] o [green]Folletto[blue]!¶Vi daremo una lezione che non dimenticherete mai!', 'scr_1FA89B4': 'Hai già finito? Guarda che non è uno scherzo. Quel grassone resterà laggiù finché qualcuno non lo salverà.', 'scr_1FA8A19': 'Credi che sia uno scherzo? Ho detto di portare solo tipi [green]Ghiaccio[blue] e [green]Folletto[blue]!¶Se vuoi salvare il grassone, dovrai fare come dico io.', 'scr_1FA8C00': "Mi arrendo. Hai vinto di nuovo.¶Ma quel grassone ha imparato la lezione, così impara a fare lo spiritoso.¶E se stare in svantaggio ti ha messo in difficoltà, l'hai imparata anche tu…", 'scr_1FA96DA': "Bene, siamo arrivati! Il Tunnel Perduto… È piuttosto umido qui dentro… È anche davvero buio.¶Non credo che nemmeno un Pokémon riuscirebbe a illuminarlo.¶Beh, meglio muoversi! C'è una scala che sale, da qualche parte qui intorno.", 'scr_1FA9867': 'Hai un coraggio sorprendente per essere così giovane, lo sai?', 'scr_1FA9B26': 'Grazie di tutto il tuo aiuto! Tieni, prendi questa MT. Mi ero scordato di averla con me per tutto questo tempo.', 'scr_1FAA159': "Che cos'era! Potrebbe essere…? No, non è possibile…", 'scr_1FAA23B': "Quel mostro era terrificante!¶Dev'essersi svegliato durante la nostra lotta di prima.¶…¶Quindi, ehm… direi che ho finito di allenare questa Ninetales, ormai…¶È ora di restituirla alla sua proprietaria.", 'scr_1FAB112': 'Accidenti! Però so che hai da fare. Torna da me appena puoi. Io resterò qui ad aspettare.', 'scr_1FAB25F': "[red]Dove credi di andare, testa matta? Il guaio è da quell'altra parte.", 'scr_1FAB2A2': '[red]Dove credi di andare, testa matta? Torni in città o roba del genere?', 'scr_1FACA10': 'Si racconta di persone che non sono mai tornate dalla Grotta del Varco. Dicono che interi gruppi scesi laggiù non siano mai stati rivisti.¶Meno male che hai salvato nostra figlia, Campione. Mi vengono i brividi al pensiero di cosa le sarebbe potuto succedere.', 'scr_1FACCD8': 'La scienziata della Società Scientifica è stata sconfitta! Riporta Electivire a Borgo Epidimy da Città Portuale.', 'scr_1FAD2A1': 'Se ho idea di dove possa essere Electivire? Ho sentito quella scienziata dire qualcosa sul recarsi a [green]Città Portuale[blue] per fare degli esperimenti…¶Ma è tutto quello che posso dirti.', 'scr_1FAD346': 'Dici di aver salvato il mio Electivire dalla scienziata? Allora ti prego, riportamelo!', 'scr_1FAD6AA': "Eh, eh, eh, urk… Sono delusa che il mio esperimento non abbia retto.¶Tuttavia… C'è sempre un piano di riserva!¶Eh, eh, eh, ah, ah!", 'scr_1FADB4F': 'Urk…¶La Società Scientifica sarà molto delusa quando saprà del mio fallimento.¶Però… sono comunque riuscita a sfruttare il potere delle Grotte Nascoste, quindi non è stata una perdita totale…¶Addio, per ora.¶Un giorno ti mostrerò il vero potere della scienza!', 'scr_1FAE053': 'Le Spade della Giustizia della regione di Unima…¶Perché dovrebbero essere qui?¶Infatti non ci sono!¶Almeno non ancora…¶Col tempo, le cose potrebbero cambiare…', 'scr_1FAE0D1': 'Le Spade della Giustizia della regione di Unima sono comparse!¶Perché dovrebbero essere qui?¶Per via del grande Boom dei Portali, ecco perché!¶Le catturerai e me le mostrerai?', 'scr_1FAE170': 'Le Spade della Giustizia aspettano che un Allenatore come il Campione venga a trovarle!¶Se non le trovi presto, potrebbe farlo qualcun altro!', 'scr_1FAE28D': "Cattura le Spade della Giustizia e portale qui!¶Si dice che siano state avvistate nei dintorni della [green]Via Vittoria[blue].¶Diffidano molto degli umani, quindi forse si sentono al sicuro solo quando sono insieme.¶Se ne sconfiggi una per sbaglio, non preoccuparti!¶Come quasi tutti i Pokémon leggendari, ricompariranno quando rientrerai nell'Albo d'oro.", 'scr_1FAE5A6': 'Ah ah! I miei sospetti erano fondati!¶Anche se le Spade della Giustizia non sono originarie di Borrius, hanno comunque un legame profondo con ciò che si nasconde dietro questa parete di roccia.¶Se ho ragione, ti serviranno questi nella lotta contro di esso.', 'scr_1FAF4CA': 'Ugh! Come ha fatto questa peste a trovarmi qui nascosto!?¶Grr… beh, allora immagino che non mi lasci altra scelta!¶Darò a una peste come te una bella lezione!', 'scr_1FAF837': "Hah! Mi piacerebbe vederti provarci!¶Quanto a te, peste… @CC0818certo, non te la sei cavata male, a battere i miei scagnozzi in quel modo…¶Ma quei codardi sono scappati davanti a una batosta facile: nessuna sorpresa che tu abbia battuto quei polli.¶Però scoprirai che io non sono un bersaglio così facile, capisci?¶Farò le cose da uomo e vedrò quanto vali davvero.¶Preparati, tu che giochi a fare l'eroe, perché Gruff sa solo giocare pesante!", 'scr_74190A': 'Sono Véga, il Capopalestra di Città Cratere.¶La cupa atmosfera di questa città mi ha permesso di concentrare tutta la mia energia oscura in un unico punto.¶Te la senti di affrontarla?', 'scr_74B441': 'Una giovane anima che corre sotto la pioggia…', 'scr_74B796': 'Giovane, non sai a cosa stai andando incontro.', 'scr_75BEDC': 'In realtà ti manca ancora parecchio.', 'scr_770AE4': 'Eh? Una peste?', 'scr_770AF0': 'Peste.', 'scr_7764EF': 'Ehilà!¶Ti do il benvenuto nel Bosco Tetro!', 'scr_7A6BB4': 'Alt! Identificati!', 'scr_7A6EED': 'Ah, solo una peste…', 'scr_7A79A2': 'Sei qui per fare guai?', 'scr_788132': 'Te lo dico io, sei più forte di questo Asso degli Escursionisti!', 'scr_788F90': 'Oh, aspetta. Sembra che non potremo lottare, per ora. Ti servirà più di un Pokémon se vuoi affrontarmi…', 'scr_792D32': 'Limpida come la tua vittoria…', 'scr_7A7357': 'Siamo davvero in alto!', 'scr_787EE7': 'Io so lottare, ma i miei Pokémon…', 'scr_7BAD86': 'Shh, piccolo Pokémon smarrito, non piangere.¶Ci sono qui io a prendermi cura di te!', 'scr_7C228A': 'È evidente che Mel non è qui.', 'scr_7C4614': "Ti do il benvenuto all'ultimo piano.", 'scr_7C4633': 'La fine è ancora lontana.', 'scr_7C4915': "Sono l'ultimo Allenatore prima di Maxima. Te la senti?", 'scr_7C7A12': 'Sei una minaccia troppo grande per lasciarti in vita.', 'scr_7CE683': "Incredibile!¶Mi hai sconfitto senza il potere della Megaevoluzione!¶Nonostante avessi tutti i pronostici contro, ce l'hai fatta lo stesso!¶Congratulazioni!", 'scr_7D65AC': 'No…¶Non può essere…', 'scr_7EA8E3': 'Mancava poco, però.', 'scr_7ED1D8': 'Anche tu scoppi di vitalità!', 'scr_7F73AA': 'Oh? Proprio tu vorresti insegnarmi qualcosa sui Pokémon?', 'scr_1F20F25': 'addormentarsi', 'scr_1EEE5EF': 'ascoltare la radio', 'scr_1F8E03A': 'È fatto. Ci vediamo [buffer1].', 'scr_1F8E0CD': 'Andrò avanti [buffer1].', 'scr_1F8E19B': 'Ottime scelte! Ci vediamo [buffer1]!', 'scr_1F8D540': "Congratulazioni per la tua striscia di vittorie, sfidante!¶Ti informiamo che [buffer1] ti tiene d'occhio e che [buffer2] ha apprezzato le tue lotte.¶[buffer3] riconosce il tuo valore, e [buffer2] vorrebbe sfidarti a una lotta!¶Te la senti di affrontare [buffer1]?", 'scr_1F8DA71': "Congratulazioni!¶La tua vittoria contro [buffer1] è stata d'ispirazione!¶Per rendere omaggio al tuo talento, ti consegniamo dei BP!", 'scr_1F8C8FD': 'La lotta contro questo Allenatore sarà una [green]@08[black] nella categoria [green]@07[black].¶La tua squadra sarà impostata al livello [green]@09[black] e le Lotte Inverse saranno [green]@0B[black].¶I Pokémon [green]@0C[black] anche usare il Dynamax.¶Scegli una squadra di [green]@0A[black] Pokémon con cui combattere.', 'scr_1F8C9F3': "La lotta contro l'Asso del Parco sarà una [green]Lotta Singola[black] nella categoria [green]@07[black].¶La tua squadra sarà impostata al livello [green]@09[black] e le Lotte Inverse saranno [green]disattivate[black].¶I Pokémon [green]@0C[black] anche usare il Dynamax.¶Scegli una squadra di [green]3[black] Pokémon con cui combattere.", 'scr_1F7B65F': 'Megapolsiera', 'scr_1F940F9': 'Oro', 'scr_1F940FE': 'Argento', 'scr_1EEE8A5': 'figo', 'scr_A4C5E5': 'Ripeti'}
